export function itemArt(key){
  const box=HILL_ART.boxes[key];if(box)return `<svg class="pixel-icon hill-icon" viewBox="${box.join(' ')}" aria-hidden="true"><image href="${HILL_ART.file}" width="${HILL_ART.width}" height="${HILL_ART.height}"/></svg>`;
  let rects=sprites[key]||sprites.lantern;
  if(key==='wheatSeed'||key==='pumpkinSeed')rects=[[4,2,8,2,'#7f5c37'],[5,4,6,1,'#c59b64'],[3,5,10,9,'#775b36'],[4,5,8,8,'#e7cb92'],[5,6,2,6,'#f4dfaf'],[6,8,4,3,key==='wheatSeed'?'#9a873e':'#d77937'],[8,7,1,2,'#567646']];
  return `<svg class="pixel-icon" viewBox="0 0 16 16" aria-hidden="true" shape-rendering="crispEdges">${rects.map(([x,y,w,h,c])=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${c}"/>`).join('')}</svg>`;
}

